        new("temperance03", DoctrineBranch.Temperance, 3, "", "금욕의 서원\u001FVow of Abstinence", "욕망을 끊겠다는 서원이 기도를 맑게 합니다.\u001FA vow to renounce desire clears the prayers.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Lust, -5f) }, GiftedSpecial.Chance("CultPray", 5)),
        new("temperance04", DoctrineBranch.Temperance, 4, "", "정결한 몸\u001FPure Body", "정결한 몸에는 불운이 깃들기 어렵습니다.\u001FMisfortune struggles to cling to a pure body.", 1, 5, new StatModifier[] { Personal(PersonalStatId.Health, 5f) }),
        new("temperance05", DoctrineBranch.Temperance, 5, "", "깊은 명상\u001FDeep Meditation", "명상이 깊어질수록 신앙이 단단해집니다.\u001FThe deeper the meditation, the firmer the Piety.", 5, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 4f) }),
        new("temperance06a", DoctrineBranch.Temperance, 6, "A", "고요한 성소\u001FSilent Sanctuary", "고요한 성소에서 해마다 마음을 다잡습니다.\u001FEach year, the silent sanctuary steadies the heart.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.LeaderFaith, 10)),
        new("temperance06b", DoctrineBranch.Temperance, 6, "B", "명상 교실\u001FMeditation Classes", "누구나 와서 명상을 배울 수 있습니다.\u001FAnyone can come and learn to meditate.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 5f), Cult(StatId.LeaderFaith, 3f) }),
        new("temperance07a", DoctrineBranch.Temperance, 7, "A", "욕망의 극복\u001FOvercoming Desire", "욕망이 고개를 들어도 쉽게 자라지 않습니다.\u001FEven when desire stirs, it does not easily grow.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Greed, -10f), Personal(PersonalStatId.Appetite, -10f), Personal(PersonalStatId.Lust, -10f) }),
        new("temperance07b", DoctrineBranch.Temperance, 7, "B", "단식 수련회\u001FFasting Retreat", "몸을 비울수록 기도가 깊어집니다.\u001FThe emptier the body, the deeper the prayer.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Health, -3f) }, GiftedSpecial.Chance("CultPray", 8)),
        new("temperance08a", DoctrineBranch.Temperance, 8, "A", "수도원\u001FMonastery", "수도원의 담장이 세상의 불운을 막아 줍니다.\u001FThe monastery walls keep the world's misfortune out.", 1, 10, new StatModifier[] { Cult(StatId.FollowerFaith, 5f) }),
        new("temperance08b", DoctrineBranch.Temperance, 8, "B", "고요의 서\u001FThe Book of Stillness", "명상의 가르침을 책으로 엮습니다.\u001FYou bind the teachings of meditation into a book.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 8f), Cult(StatId.LeaderFaith, 5f) }),
        new("temperance09a", DoctrineBranch.Temperance, 9, "A", "무소유\u001FNon-Possession", "가진 것을 모두 내려놓습니다.\u001FYou let go of everything you own.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, -10f), Cult(StatId.LeaderFaith, 12f), Cult(StatId.Reputation, 5f) }),
        new("temperance09b", DoctrineBranch.Temperance, 9, "B", "마음 수련원\u001FRetreat Center", "수련원에서 해마다 신도들이 마음을 다잡습니다.\u001FEach year at the retreat center, followers steady their hearts.", 1, 5, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.FollowerFaith, 10)),
        new("temperance10a", DoctrineBranch.Temperance, 10, "A", "해탈의 경지\u001FLiberation", "어떤 불운도 교주의 마음을 흔들지 못합니다.\u001FNo misfortune can shake the cult leader's mind.", 2, 15, new StatModifier[] { Cult(StatId.LeaderFaith, 15f) }),
        new("temperance10b", DoctrineBranch.Temperance, 10, "B", "깨달음의 등불\u001FLamp of Enlightenment", "교주의 깨달음이 등불처럼 신도들을 비춥니다.\u001FYour enlightenment lights the way for your followers like a lamp.", 2, 10, new StatModifier[] { Cult(StatId.LeaderFaith, 10f), Cult(StatId.FollowerFaith, 10f) }),
        new("charity01", DoctrineBranch.Charity, 1, "", "이웃 사랑\u001FLove Thy Neighbor", "이웃을 돕는 교단이라는 말이 돕니다.\u001FWord spreads of a cult that helps its neighbors.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 5f) }),
        new("charity02", DoctrineBranch.Charity, 2, "", "무료 급식\u001FFree Meals", "배고픈 이에게 밥을 나눕니다.\u001FYou share food with the hungry.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.Chance("Serve", 5)),
        new("charity03", DoctrineBranch.Charity, 3, "", "병자 돌봄\u001FCaring for the Sick", "아픈 이의 곁을 지킵니다.\u001FYou stay by the side of the sick.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 5f), Cult(StatId.FollowerFaith, 3f) }),
        new("charity04", DoctrineBranch.Charity, 4, "", "구호 기금\u001FRelief Fund", "해마다 구호 기금이 이웃을 돕습니다.\u001FEach year, the relief fund helps your neighbors.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.Reputation, 5)),
        new("charity05", DoctrineBranch.Charity, 5, "", "베푸는 손\u001FGiving Hand", "베풀수록 교단의 이름이 빛납니다.\u001FThe more you give, the brighter the cult's name shines.", 5, 0, new StatModifier[] { Cult(StatId.Reputation, 4f) }),
        new("charity06a", DoctrineBranch.Charity, 6, "A", "고아원\u001FOrphanage", "교단이 갈 곳 없는 아이들을 품습니다.\u001FThe cult takes in children with nowhere to go.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 5f), Personal(PersonalStatId.Charity, 5f) }),
        new("charity06b", DoctrineBranch.Charity, 6, "B", "무료 진료소\u001FFree Clinic", "돈이 없어도 누구나 치료받을 수 있습니다.\u001FAnyone can be treated, even without money.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 5f), Personal(PersonalStatId.Health, 5f) }),
        new("charity07a", DoctrineBranch.Charity, 7, "A", "자선 바자회\u001FCharity Bazaar", "바자회 수익이 모두 이웃에게 갑니다.\u001FEvery cent of the bazaar's proceeds goes to the neighbors.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, -5f) }, GiftedSpecial.Chance("Serve", 10)),
        new("charity07b", DoctrineBranch.Charity, 7, "B", "야학\u001FNight School", "밤마다 배움에 목마른 이들을 가르칩니다.\u001FEvery night, you teach those who thirst for learning.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 6f), Personal(PersonalStatId.Mentality, 5f) }),
        new("charity08a", DoctrineBranch.Charity, 8, "A", "화해의 손길\u001FHand of Reconciliation", "다른 종교와도 손을 잡습니다.\u001FYou join hands even with other religions.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.Reputation, 10)),
        new("charity08b", DoctrineBranch.Charity, 8, "B", "교단 병원\u001FCult Hospital", "교단 병원이 해마다 이웃의 신뢰를 쌓습니다.\u001FEach year, the cult hospital builds your neighbors' trust.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.Reputation, 8)),
        new("charity09a", DoctrineBranch.Charity, 9, "A", "만인의 집\u001FHouse for All", "누구든 교단의 문을 두드릴 수 있습니다.\u001FAnyone may knock on the cult's door.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 10f), Cult(StatId.Reputation, 8f) }),
        new("charity09b", DoctrineBranch.Charity, 9, "B", "학교 설립\u001FFounding a School", "교단의 학교에서 아이들이 자랍니다.\u001FChildren grow up in the cult's school.", 1, 0, new StatModifier[] { Cult(StatId.Followers, 8f), Cult(StatId.Doctrine, 5f) }),
        new("charity10a", DoctrineBranch.Charity, 10, "A", "성인의 교단\u001FCult of Saints", "세상은 교단을 성인들의 공동체라 부릅니다.\u001FThe world calls your cult a community of saints.", 2, 0, new StatModifier[] { Cult(StatId.Reputation, 15f), Cult(StatId.FollowerFaith, 10f) }),
        new("charity10b", DoctrineBranch.Charity, 10, "B", "치유의 성전\u001FTemple of Healing", "병든 이들이 성전을 찾아 길게 줄을 섭니다.\u001FThe sick line up in long queues outside the temple.", 2, 0, new StatModifier[] { Cult(StatId.Reputation, 12f), Cult(StatId.Followers, 10f) }, GiftedSpecial.Yearly(PersonalStatId.Health, 2)),
        new("patience01", DoctrineBranch.Patience, 1, "", "견디는 마음\u001FEnduring Heart", "참는 법을 배운 신도들이 쉽게 흔들리지 않습니다.\u001FFollowers who learn to endure are not easily shaken.", 1, 3, new StatModifier[] { Personal(PersonalStatId.Patience, 5f) }),
        new("patience02", DoctrineBranch.Patience, 2, "", "고행의 길\u001FPath of Penance", "실패한 기도마저 수행이 됩니다.\u001FEven failed prayers become part of the discipline.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.FailHalf("CultPray")),
        new("patience03", DoctrineBranch.Patience, 3, "", "긴 기도\u001FLong Prayers", "밤을 새우는 기도가 몸과 마음을 단련합니다.\u001FAll-night prayer tempers body and mind.", 1, 0, new StatModifier[] { Cult(StatId.LeaderFaith, 5f), Personal(PersonalStatId.Health, 3f) }),
        new("patience04", DoctrineBranch.Patience, 4, "", "단련된 신도\u001FTempered Followers", "고된 수행을 거친 신도들이 쉽게 꺾이지 않습니다.\u001FFollowers hardened by grueling discipline do not easily break.", 1, 5, new StatModifier[] { Cult(StatId.FollowerFaith, 5f) }),
        new("patience05", DoctrineBranch.Patience, 5, "", "버팀목\u001FPillar of Support", "시련이 거듭될수록 교단이 단단해집니다.\u001FThe more trials you face, the stronger the cult becomes.", 5, 4, System.Array.Empty<StatModifier>()),
        new("patience06a", DoctrineBranch.Patience, 6, "A", "시련의 해석\u001FReading the Trials", "실패한 설교와 포교도 시련으로 받아들입니다.\u001FEven failed sermons and outreach are accepted as trials.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.FailHalf("Preach"), GiftedSpecial.FailHalf("Proselytize")),
        new("patience06b", DoctrineBranch.Patience, 6, "B", "비폭력 서약\u001FVow of Nonviolence", "어떤 핍박에도 손을 들지 않겠다고 맹세합니다.\u001FYou swear never to raise a hand, whatever the persecution.", 1, 3, new StatModifier[] { Cult(StatId.Reputation, 5f) }),
        new("patience07a", DoctrineBranch.Patience, 7, "A", "굳건한 반석\u001FSolid Rock", "해마다 몸과 교단이 더 단단해집니다.\u001FEach year, your body and your cult grow stronger.", 1, 5, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(PersonalStatId.Health, 2)),
        new("patience07b", DoctrineBranch.Patience, 7, "B", "침묵 행진\u001FSilent March", "말없이 걷는 행렬이 사람들의 마음을 움직입니다.\u001FA wordless procession moves people's hearts.", 1, 0, new StatModifier[] { Cult(StatId.Reputation, 3f) }, GiftedSpecial.Chance("Proselytize", 8)),
        new("patience08a", DoctrineBranch.Patience, 8, "A", "박해를 이긴 자들\u001FThose Who Overcame Persecution", "박해를 견딘 이야기가 신도들을 뜨겁게 합니다.\u001FTales of enduring persecution set your followers on fire.", 1, 0, new StatModifier[] { Cult(StatId.FollowerFaith, 10f), Cult(StatId.Reputation, 5f) }),
        new("patience08b", DoctrineBranch.Patience, 8, "B", "옥중 서신\u001FLetters from Prison", "갇힌 교주의 편지가 신도들을 일으켜 세웁니다.\u001FLetters from the imprisoned cult leader rally the followers.", 1, 5, new StatModifier[] { Cult(StatId.FollowerFaith, 8f) }),
        new("patience09a", DoctrineBranch.Patience, 9, "A", "끝없는 인내\u001FEndless Patience", "어떤 실패도 반만큼만 아픕니다.\u001FEvery failure hurts only half as much.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.FailHalf("All")),
        new("patience09b", DoctrineBranch.Patience, 9, "B", "박해의 기록\u001FRecord of Persecution", "박해의 기록이 세상의 양심을 깨웁니다.\u001FThe record of persecution awakens the world's conscience.", 1, 0, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.Reputation, 8), GiftedSpecial.FailHalf("Serve")),
        new("patience10a", DoctrineBranch.Patience, 10, "A", "순교자의 교단\u001FCult of Martyrs", "불운이 닥쳐도 교단은 무너지지 않습니다.\u001FEven when misfortune strikes, the cult does not fall.", 2, 20, new StatModifier[] { Cult(StatId.FollowerFaith, 10f) }),
        new("patience10b", DoctrineBranch.Patience, 10, "B", "불굴의 행렬\u001FUnbreakable Procession", "꺾이지 않는 행렬 앞에 세상이 길을 엽니다.\u001FThe world parts before a procession that will not bend.", 2, 15, new StatModifier[] { Cult(StatId.Reputation, 10f), Cult(StatId.FollowerFaith, 10f) }),
        new("integrity01", DoctrineBranch.Integrity, 1, "", "정직한 장부\u001FHonest Ledger", "장부를 숨기지 않습니다.\u001FYou hide nothing in the books.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Integrity, 5f), Cult(StatId.Reputation, 3f) }),
        new("integrity02", DoctrineBranch.Integrity, 2, "", "투명한 헌금\u001FTransparent Offerings", "헌금이 어디에 쓰이는지 모두가 압니다.\u001FEveryone knows where the Offerings go.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 3f), Cult(StatId.Reputation, 3f) }),
        new("integrity03", DoctrineBranch.Integrity, 3, "", "진실의 설교\u001FSermon of Truth", "꾸밈없는 설교가 마음에 닿습니다.\u001FUnadorned sermons reach the heart.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 5f) }, GiftedSpecial.Chance("Preach", 5)),
        new("integrity04", DoctrineBranch.Integrity, 4, "", "교리 연구\u001FDoctrine Study", "교리를 다듬고 또 다듬습니다.\u001FYou refine the Doctrine again and again.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 8f) }),
        new("integrity05", DoctrineBranch.Integrity, 5, "", "깨끗한 이름\u001FClean Name", "정직이 쌓일수록 이름이 깨끗해집니다.\u001FThe more honesty builds up, the cleaner your name becomes.", 5, 0, new StatModifier[] { Cult(StatId.Reputation, 4f) }),
        new("integrity06a", DoctrineBranch.Integrity, 6, "A", "공개 회계\u001FPublic Accounts", "해마다 회계를 공개해 신뢰를 얻습니다.\u001FEach year, you publish your accounts and earn trust.", 1, 0, new StatModifier[] { Cult(StatId.Offerings, 3f) }, GiftedSpecial.Yearly(StatId.Reputation, 5)),
        new("integrity06b", DoctrineBranch.Integrity, 6, "B", "율법 학교\u001FSchool of Law", "교리를 법처럼 가르치는 학교를 엽니다.\u001FYou open a school that teaches Doctrine like law.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 6f), Cult(StatId.Authority, 3f) }),
        new("integrity07a", DoctrineBranch.Integrity, 7, "A", "경전 편찬\u001FCompiling the Scripture", "교리를 정리한 경전을 펴냅니다.\u001FYou publish a scripture that sets the Doctrine in order.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 10f) }, GiftedSpecial.Yearly(StatId.Doctrine, 10)),
        new("integrity07b", DoctrineBranch.Integrity, 7, "B", "교단 법정\u001FCult Tribunal", "교단 안의 다툼을 교단 법정이 가립니다.\u001FThe cult tribunal settles disputes within the cult.", 1, 0, new StatModifier[] { Cult(StatId.Authority, 6f) }, GiftedSpecial.Chance("Preach", 5)),
        new("integrity08a", DoctrineBranch.Integrity, 8, "A", "정의로운 판결\u001FRighteous Verdict", "공정한 판결이 교단을 지켜 줍니다.\u001FFair verdicts protect the cult.", 1, 5, new StatModifier[] { Cult(StatId.Authority, 5f), Cult(StatId.Reputation, 5f) }),
        new("integrity08b", DoctrineBranch.Integrity, 8, "B", "성문 율법\u001FWritten Law", "율법을 글로 새겨 모두가 지키게 합니다.\u001FYou carve the law into writing so all must keep it.", 1, 0, new StatModifier[] { Cult(StatId.Doctrine, 10f), Cult(StatId.Reputation, 3f) }),
        new("integrity09a", DoctrineBranch.Integrity, 9, "A", "부패 척결\u001FRooting Out Corruption", "교단 안의 부패를 뿌리 뽑습니다.\u001FYou tear out corruption within the cult by the roots.", 1, 0, new StatModifier[] { Personal(PersonalStatId.Greed, -10f) }, GiftedSpecial.Yearly(StatId.Reputation, 10)),
        new("integrity09b", DoctrineBranch.Integrity, 9, "B", "공정한 재판관\u001FFair Judge", "공정한 재판이 해마다 교리를 다듬습니다.\u001FEach year, fair trials refine the Doctrine.", 1, 5, System.Array.Empty<StatModifier>(), GiftedSpecial.Yearly(StatId.Doctrine, 10)),
        new("integrity10a", DoctrineBranch.Integrity, 10, "A", "빛의 교단\u001FCult of Light", "빛 아래 숨길 것이 없는 교단이 되었습니다.\u001FYour cult has nothing left to hide in the light.", 2, 10, new StatModifier[] { Cult(StatId.Reputation, 15f), Cult(StatId.Doctrine, 15f) }),
        new("integrity10b", DoctrineBranch.Integrity, 10, "B", "율법의 수호자\u001FGuardian of the Law", "교단은 흔들리지 않는 율법 위에 섰습니다.\u001FThe cult stands on an unshakable law.", 2, 8, new StatModifier[] { Cult(StatId.Doctrine, 15f), Cult(StatId.Authority, 10f) }),
    };

    public static DoctrineSkill Find(string id) => id == DoctrineSkill.DeclarationId ? DoctrineSkill.Declaration : All.FirstOrDefault(s => s.Id == id);

    // 6~10단계는 갈래(A/B)를 지정한다
    public static DoctrineSkill At(DoctrineBranch branch, int tier, string path = "") => All.FirstOrDefault(s => s.Branch == branch && s.Tier == tier && s.Path == (tier <= 5 ? "" : path));
}
